import{_ as p,o as t,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph Science Working Group 2021-03-24","description":"","frontmatter":{"title":"Ceph Science Working Group 2021-03-24","date":"2021-03-24T00:00:00.000Z","updated":"2021-03-27T00:00:00.000Z","tags":["Ceph","分布式存储","版本升级","高可用性","自动化","社区活动"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Science_Working_Group_2021-03-24.md","filePath":"posts/2021/Ceph_Science_Working_Group_2021-03-24.md","lastUpdated":1780460162000}'),n={name:"posts/2021/Ceph_Science_Working_Group_2021-03-24.md"};function r(s,e,l,h,_,a){return t(),o("div",null,[...e[0]||(e[0]=[i("<p>本次会议是Ceph Science Working Group的一次非正式讨论会，主要参与者为使用Ceph分布式存储系统的用户，尤其是管理大型集群的用户。会议主要围绕Ceph的最新问题、升级计划、性能讨论以及未来发展方向展开。</p><p><strong>主要议题</strong>：</p><ol><li><p><strong>Ceph MDS问题</strong>： 讨论了MDS在重新加入集群时可能消耗大量内存的问题，特别是在使用8GB RAM的MDS时，可能会消耗高达60GB的内存。提到了在Ceph Octopus版本中可能存在的修复。</p></li><li><p><strong>Ceph版本升级</strong>： 讨论了从Ceph Nautilus升级到Ceph Octopus的计划，以及升级过程中可能遇到的问题。提到了Ceph Pacific版本的一些新特性和潜在问题，如S3对象消失的问题，但已修复。</p></li><li><p><strong>Ceph管理与部署</strong>： 讨论了使用Cephadm进行集群管理的经验，包括容器化部署的优缺点。提到了Cephadm在处理大规模集群时的性能问题，以及未来可能的改进方向。</p></li><li><p><strong>Ceph社区活动</strong>： 讨论了即将到来的Ceph Month活动，这是一个替代Cephalocon的线上活动，旨在通过分散的线上会议来减少参会者的疲劳。讨论了如何组织和选择会议内容，以及如何记录和分享这些讨论。</p></li></ol><p><strong>决定事项</strong>：</p><ul><li>确定了Ceph Month活动的初步计划和形式，包括可能的会议频率和内容选择方式。</li><li>讨论了Ceph版本升级的具体计划，包括从Nautilus到Octopus的升级路径和潜在风险。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续监控和测试Ceph MDS的性能问题，特别是在高负载情况下的表现。</li><li>继续推进Ceph版本的升级计划，特别是从Nautilus到Octopus的升级。</li><li>准备Ceph Month活动的具体安排，包括会议内容的征集和筛选。</li></ul><p><strong>其他讨论点</strong>：</p><ul><li>讨论了Ceph在不同操作系统和环境下的兼容性和性能问题，特别是与Python版本相关的编译问题。</li><li>讨论了Ceph在不同使用场景下的最佳实践，包括文件系统的快照管理和Erasure Coding的使用。</li></ul><p>本次会议为Ceph社区提供了一个交流和分享的平台，有助于推动Ceph技术的发展和改进。</p>",10)])])}const u=p(n,[["render",r]]);export{C as __pageData,u as default};
